def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    def comps8(color):
        seen=set(); out=[]
        for r in range(h):
            for c in range(w):
                if g[r][c]!=color or (r,c) in seen: continue
                stack=[(r,c)]; seen.add((r,c)); pts=[]
                while stack:
                    x,y=stack.pop(); pts.append((x,y))
                    for a in range(max(0,x-1),min(h,x+2)):
                        for b in range(max(0,y-1),min(w,y+2)):
                            if g[a][b]==color and (a,b) not in seen:
                                seen.add((a,b)); stack.append((a,b))
                out.append(pts)
        return out
    def shape(pts):
        r0=min(r for r,c in pts); c0=min(c for r,c in pts)
        return frozenset((r-r0,c-c0) for r,c in pts)
    # Find same-shaped target-colored (9) object as the non-background 4 template.
    refs=comps8(4)
    if refs:
        key=shape(max(refs,key=len))
        for obj in comps8(9):
            if shape(obj)==key:
                for r,c in obj: g[r][c]=7
                break
    return g
